 "content": "from collections import Counter, deque


def transform(grid):
    """Find the largest connected foreground patch, ignoring the three noisy background colors."""
    h, w = len(grid), len(grid[0])
    counts = Counter(value for row in grid for value in row)
    background = {color for color, _ in counts.most_common(3)}
    seen = [[False] * w for _ in range(h)]
    best_color = None
    best_size = -1
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if seen[r][c] or color in background:
                continue
            seen[r][c] = True
            q = deque([(r, c)])
            size = 0
            while q:
                y, x = q.popleft()
                size += 1
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        q.append((ny, nx))
            if size > best_size:
                best_color, best_size = color, size
    return [[best_color] * 3 for _ in range(3)]
